const icon = name => `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
const esc = v => String(v ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date = v => v ? new Date(v.length===10?`${v}T12:00:00`:v).toLocaleDateString('pt-BR') : '—';
const time = v => v ? new Date(v).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit',timeZone:'America/Sao_Paulo'}) : '—';
const localDay = v => new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(v||Date.now()));
const initials = n => String(n||'RH').split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const person = e => `<div class="person"><div class="avatar ${Number(e.id)%2?'alt':''}">${esc(initials(e.name))}</div><div class="who"><b>${esc(e.name)}</b><small>${esc(e.role||'')}</small></div></div>`;
const brand = () => `<div class="brand"><img src="/assets/logo.png" alt="Logo Radeane"><div><strong>${esc(data?.settings?.institution||'Portal Radeane')}</strong><small>Gestão de pessoas</small></div></div>`;
const pill = s => `<span class="tag ${['Ativo','Aprovado','Aceito'].includes(s)?'green':['Recusado','Inativo'].includes(s)?'red':['Pendente','Pendente de correção','Recebido'].includes(s)?'amber':'blue'}">${esc(s)}</span>`;
const btn = (label,action,id='',cls='primary',ico='plus') => `<button type="button" class="btn ${cls}" data-action="${action}" data-id="${esc(id)}">${ico?icon(ico):''}${esc(label)}</button>`;
const empty = (title='Ainda não há registros',sub='Os novos registros aparecerão aqui.',ico='file') => `<div class="empty">${icon(ico)}<b>${esc(title)}</b>${esc(sub)}</div>`;
const personalFields=[['nickname','Apelido'],['nationality','Nacionalidade'],['birthplace','Naturalidade'],['birth_state','UF de nascimento'],['birthday','Data de nascimento'],['postal_code','CEP'],['address','Endereço'],['address_number','Número'],['neighborhood','Bairro'],['city','Cidade'],['state','UF']];
const personalData=e=>{try{return JSON.parse(e.personal_data||'{}')||{};}catch{return {};}};
const emp = id => data.employees.find(e=>e.id===Number(id))||{name:'Colaborador',role:'',id};
const options = (items, selected, label='name') => items.map(e=>`<option value="${e.id}" ${Number(selected)===e.id?'selected':''}>${esc(e[label])}</option>`).join('');
const table = (heads,rows) => rows.length ? `<div class="table-scroll"><table class="data-table"><thead><tr>${heads.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>` : empty();
const field = (label,name,type='text',value='',required=true) => `<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='password'?'minlength="12" maxlength="200" autocomplete="new-password"':''}></label>`;
const select = (label,name,opts) => `<label>${label}<select name="${name}" aria-label="${esc(label)}" required>${opts}</select></label>`;
const noteField = (label='Observação (opcional)',value='') => `<label>${label}<textarea name="notes" maxlength="2000">${esc(value)}</textarea></label>`;
function toast(text) {const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),5000);}
async function api(path,method='GET',body) {
  if(demo) return demoApi(path,method,body);
  const r = await fetch('/api'+path,{method,headers:{'Content-Type':'application/json','X-CSRF-Token':csrf||''},...(body?{body:JSON.stringify(body)}:{})});
  const result=await r.json();if(!r.ok){if(r.status===401&&user){user=null;renderAuth(false);}throw new Error(result.error||'Não foi possível concluir.');}return result;
}
