function demoApi(path,method,b={}) {
  if(path==='/system'&&method==='GET')return{version:'0.2.0',runtime:'PHP (demonstração)',database:'Demonstração',structure:{PUBLIC:'Arquivos visuais',RH:'Aplicação privada'},migrations:[],settings:{}};
  if(path.startsWith('/system/')||path.startsWith('/import/')||path.startsWith('/reports'))throw Error('Use uma conta real para esta operação. A demonstração não executa migrações, importações ou relatórios do banco.');
  if(path==='/data')return data;
  if(path==='/me')return{user,csrf:'demo'};
  const resource=path.split('/')[1],id=Number(path.split('/')[2]);
  if(path==='/punches'){if(isManager())throw Error('No tablet, selecione o perfil demonstrativo do funcionário.');const kinds=['Entrada','Saída para intervalo','Retorno do intervalo','Saída'];const last=data.punches.find(x=>x.employee_id===user.employee_id);const next=!last||last.kind==='Saída'?'Entrada':kinds[kinds.indexOf(last.kind)+1];if(b.kind!==next)throw Error(`A próxima marcação é: ${next}`);data.punches.unshift({id:Date.now(),employee_id:user.employee_id,kind:b.kind,at:new Date().toISOString()});}
  else if(method==='PATCH'){const row=data[resource]?.find(r=>r.id===id);if(row)Object.assign(row,b);if(resource==='employees'){row.sector_id=Number(b.sector_id)||null;row.sector=data.sectors.find(s=>s.id===row.sector_id)?.name||'';}}
  else if(method==='POST'&&data[resource]){
    if(resource==='schedules'){b.days=JSON.stringify(b.days);data.schedules=data.schedules.filter(s=>s.employee_id!==Number(b.employee_id));}
    if(b.start&&b.end&&b.end<b.start)throw Error('O fim deve ser igual ou posterior ao início.');
    if(resource==='leaves'&&data.leaves.some(x=>x.employee_id===Number(b.employee_id)&&x.status!=='Recusado'&&x.start<=b.end&&x.end>=b.start))throw Error('Já existe uma solicitação nesse período.');
    const row={...b,id:Date.now(),created:new Date().toISOString(),employee_id:Number(b.employee_id),status:resource==='documents'?'Recebido':resource==='employees'?'Ativo':'Pendente'};
    if(resource==='employees'){row.sector_id=Number(b.sector_id)||null;row.sector=data.sectors.find(s=>s.id===row.sector_id)?.name||'';}
    if(resource==='documents'){row.original_name=b.filename;demoFiles.set(row.id,b);delete row.base64;}
    if(resource==='users'){if(data.users.some(u=>u.employee_id===row.employee_id))throw Error('Esse colaborador já tem acesso.');row.name=emp(row.employee_id).name;row.role='employee';row.active=1;delete row.password;}
    data[resource].unshift(row);
    data.audit.unshift({id:Date.now(),actor:user.name,action:'Registro de demonstração criado',detail:resource,at:new Date().toISOString()});return{id:row.id};
  }
  data.audit.unshift({id:Date.now(),actor:user.name,action:'Registro demonstrativo atualizado',detail:resource,at:new Date().toISOString()});return{ok:true};
}
function banner(){return demo?`<div class="demo-banner"><span><b>Modo demonstração</b> · Dados fictícios. Alterações duram até recarregar esta página.</span><button data-action="exit-demo">Configurar meu RH ${icon('arrow')}</button></div>`:'';}
const navItems=[['dashboard','Visão geral','grid'],['equipe','Colaboradores','people'],['frequencia','Frequência e ponto','clock'],['escalas','Escalas e folgas','calendar'],['ferias','Férias e ausências','sun'],['horarios','Jornadas e aulas','clock'],['setores','Setores do colégio','building'],['documentos','Documentos e atestados','file'],['pendencias-documentais','Pendências documentais','file'],['premiacao','Critérios e premiação','award'],['indicadores','Indicadores e medições','activity'],['tarefas','Tarefas e entregas','calendar'],['organizacao','Organização e incentivos','building'],['talentos','Banco de talentos','people'],['usuarios','Usuários e acessos','shield'],['auditoria','Histórico de alterações','activity'],['importacao','Importar colaboradores','upload'],['relatorios','Relatórios','file'],['sistema','Administração do sistema','settings']];
