function layout(content,id){
  app.innerHTML=`<div class="shell"><button class="mobile-nav-backdrop" data-action="menu" aria-label="Fechar menu"></button><aside class="sidebar">${brand()}<nav><div class="nav-label">ESPAÇO DE TRABALHO</div>${navItems.slice(0,8).map(n=>`<a class="nav-link ${id===n[0]?'active':''}" href="#${n[0]}">${icon(n[2])}${n[1]}</a>`).join('')}<div class="nav-label">GESTÃO E CONTROLE</div>${navItems.slice(8).filter(n=>n[0]!=='sistema'||user.role==='system_admin').map(n=>`<a class="nav-link ${id===n[0]?'active':''}" href="#${n[0]}">${icon(n[2])}${n[1]}</a>`).join('')}<div class="nav-label">ACESSO RÁPIDO</div><a href="/ponto" class="nav-link" data-action="portal" data-id="ponto">${icon('clock')}Ponto na recepção</a><a href="/atestados" class="nav-link" data-action="portal" data-id="atestados">${icon('upload')}Portal de atestados</a></nav><div class="side-foot"><div class="person"><div class="avatar">${initials(user.name)}</div><div class="who"><b>${esc(user.name)}</b><small>${esc(roleLabel(user.role))}</small></div><button class="icon-btn" data-action="logout" title="Sair" aria-label="Sair">${icon('exit')}</button></div></div></aside><main><header class="topbar"><div class="crumb"><button class="icon-btn mobile-toggle" data-action="menu" aria-label="Abrir menu">${icon('menu')}</button><span>Gestão de pessoas</span><span>/</span><b>${esc(navItems.find(n=>n[0]===id)?.[1]||'Prontuário do colaborador')}</b></div><div class="top-actions"><small><span class="status-dot"></span>${demo?'Ambiente de demonstração':'Ambiente online'}</small><button class="icon-btn" data-action="password" title="Alterar senha" aria-label="Alterar senha">${icon('settings')}</button><div class="person"><div class="avatar">${initials(user.name)}</div><div class="who"><b>${esc(user.name)}</b><small>Recursos humanos</small></div></div></div></header><div class="workspace">${banner()}${content}<footer class="footer"><span>Instituto Educacional Radeane · Gestão de Pessoas</span><span>${demo?'Demonstração interativa':'PHP · 0.4'}</span></footer></div></main></div>`;
}
const heading = (tag,title,sub,action='') => `<div class="heading"><div><div class="eyebrow">${esc(tag)}</div><h1>${esc(title)}</h1><p>${esc(sub)}</p></div><div class="action-row">${action}</div></div>`;
function dashboard(){
  const active=data.employees.filter(e=>e.status==='Ativo'),today=localDay(),present=new Set(data.punches.filter(p=>localDay(p.at)===today).map(p=>p.employee_id));
  const docs=data.documents.filter(d=>['Recebido','Em análise','Pendente de correção'].includes(d.status)),leaves=data.leaves.filter(l=>l.status==='Pendente');
  const stats=[['Colaboradores ativos',active.length,`${data.sectors.length} setores cadastrados`,'people'],['Ponto registrado hoje',present.size,'Colaboradores com marcação no dia','clock'],['Solicitações pendentes',leaves.length,'Férias, folgas e ausências','calendar'],['Documentos para análise',docs.length,'Atestados e justificativas','file']];
  return `${heading('Pessoas fazem a diferença','Sua equipe, em um só lugar.','Acompanhe as rotinas e cuide de quem faz parte do Radeane.',btn('Novo colaborador','employee'))}<div class="stats">${stats.map((s,i)=>`<div class="card stat"><div class="stat-top">${s[0]}<span class="stat-icon ${i===2?'coral':''}">${icon(s[3])}</span></div><div class="stat-value">${s[1].toString().padStart(2,'0')}</div><small>${s[2]}</small></div>`).join('')}</div><div class="grid-main"><div class="card padded-table"><div class="card-head"><h2>Movimentações de hoje</h2><a href="#frequencia">Ver frequência →</a></div>${table(['Colaborador','Marcação','Horário','Registro'],data.punches.filter(p=>localDay(p.at)===today).slice(0,5).map(p=>`<tr><td><a href="#colaborador/${p.employee_id}">${person(emp(p.employee_id))}</a></td><td>${esc(p.kind)}</td><td>${time(p.at)}</td><td>${pill('Registrado')}</td></tr>`))}</div><div class="card"><div class="card-head"><h2>Distribuição por setor</h2><span class="tag">${data.sectors.length} setores</span></div>${data.sectors.map(s=>{const count=active.filter(e=>e.sector_id===s.id).length;return `<div class="sector-row"><div><span>${esc(s.name)}</span><small>${count} ${count===1?'pessoa':'pessoas'}</small></div><progress max="${Math.max(active.length,1)}" value="${count}" aria-label="${esc(s.name)}"></progress></div>`}).join('')||empty('Organize suas equipes','Comece pelo cadastro dos setores.','building')}</div></div><div class="grid-main"><div class="card"><div class="card-head"><h2>Próximas ausências</h2><a href="#ferias">Abrir calendário →</a></div>${table(['Colaborador','Tipo','Período','Situação'],data.leaves.filter(l=>l.end>=today&&l.status!=='Recusado').sort((a,b)=>a.start.localeCompare(b.start)).slice(0,4).map(l=>`<tr><td><a href="#colaborador/${l.employee_id}">${person(emp(l.employee_id))}</a></td><td>${esc(l.kind)}</td><td class="nowrap">${date(l.start)} → ${date(l.end)}</td><td>${pill(l.status)}</td></tr>`))}</div><div class="card"><div class="card-head"><h2>Atalhos do seu dia</h2></div><div class="quick-grid"><a class="quick" href="#equipe">${icon('people')}Prontuários</a><a class="quick" href="#documentos">${icon('file')}Analisar atestados</a><a class="quick" href="/ponto" data-action="portal" data-id="ponto">${icon('clock')}Ponto no tablet</a><a class="quick" href="#escalas">${icon('calendar')}Escalas e folgas</a></div></div></div>`;
}
function employeesPage(){return `${heading('Nossa equipe','Colaboradores','Clique em uma pessoa para consultar seu prontuário completo.',btn('Importar planilha','import-open','','','upload')+btn('Novo colaborador','employee'))}<div class="card padded-table"><div class="filters"><div class="search">${icon('search')}<input type="search" placeholder="Buscar nome, cargo ou e-mail…" aria-label="Buscar colaboradores" data-filter="people"></div><select data-sector-filter aria-label="Filtrar setor"><option value="">Todos os setores</option>${options(data.sectors)}</select><span class="tag">${data.employees.length} colaboradores</span></div>${table(['Nome e cargo','Setor','Admissão','Situação',''],data.employees.map(e=>`<tr class="clickable" data-person-row data-sector="${e.sector_id}" data-search="${esc(`${e.name} ${e.role} ${e.email}`.toLowerCase())}"><td><a href="#colaborador/${e.id}">${person(e)}</a></td><td>${esc(e.sector||'Não definido')}</td><td>${date(e.admission)}</td><td>${pill(e.status)}${Number(e.punch_exempt)?'<br><small>Dispensado de ponto</small>':''}${!e.cpf?'<br><small>CPF pendente</small>':''}</td><td><a href="#colaborador/${e.id}" class="text-link">Abrir prontuário →</a></td></tr>`))}</div>`;}
function leaveRows(rows,actions=true){return table(['Colaborador','Tipo','Período','Situação',...(actions?['Análise']:[])],rows.map(l=>`<tr><td>${actions?`<a href="#colaborador/${l.employee_id}">${person(emp(l.employee_id))}</a>`:person(emp(l.employee_id))}</td><td>${esc(l.kind)}</td><td>${date(l.start)} → ${date(l.end)}${l.notes?`<br><small>${esc(l.notes)}</small>`:''}${l.review?`<br><small>Resposta do RH: ${esc(l.review)}</small>`:''}</td><td>${pill(l.status)}</td>${actions?`<td><div class="action-row">${btn('Analisar','review-leave',l.id,'small','')}</div></td>`:''}</tr>`));}
function leavesPage(kind){const folgas=kind==='escalas';const rows=data.leaves.filter(l=>folgas?l.kind==='Folga':l.kind!=='Folga');return `${heading('Planejamento de equipe',folgas?'Escalas e folgas':'Férias e ausências',folgas?'Consulte jornadas e organize as folgas de cada setor.':'Solicitações e períodos programados, com aprovação do RH.',btn(folgas?'Programar folga':'Nova solicitação','leave',folgas?'Folga':'Férias'))}<div class="note">Os períodos são informados pelo RH ou solicitados pelo funcionário. O sistema verifica sobreposições individuais; a cobertura mínima de cada setor precisa ser conferida pelo responsável.</div><div class="card padded-table">${leaveRows(rows)}</div>${folgas?`<div class="space-top">${scheduleCards()}</div>`:''}`;}
function scheduleCards(employeeId){const links=(data.work_assignments||[]).filter(a=>!employeeId||Number(a.employee_id)===Number(employeeId));if(links.length)return '<div class="grid-2">'+links.map(a=>{const t=JSON.parse(a.snapshot);const days=['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'];return '<article class="card"><h2>'+esc(emp(a.employee_id).name)+'</h2><h3>'+esc(t.title)+'</h3><p>'+esc(a.start)+' a '+esc(a.end||'sem término')+'</p><p>'+esc(t.kind)+'</p>'+JSON.parse(t.slots).map(slot=>'<p>'+days[slot.day]+' · '+esc(slot.start)+'–'+esc(slot.end)+' · '+esc(slot.label)+'</p>').join('')+'<p>Intervalo previsto: '+Number(t.break_minutes)+' min/dia · Hora-aula: '+Number(t.lesson_minutes)+' min</p></article>';}).join('')+'</div>';const rows=data.schedules.filter(s=>!employeeId||s.employee_id===employeeId);return rows.length?`<div class="grid-2">${rows.map(s=>`<div class="card"><div class="card-head">${person(emp(s.employee_id))}${Number(emp(s.employee_id).punch_exempt)?'<span class="tag">Horário de referência · dispensado de ponto</span>':''}${isManager()?btn('Editar','schedule',s.employee_id,'small','edit'):''}</div><span class="tag">${JSON.parse(s.days).map(d=>['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'][d]).join(' · ')}</span><div class="time-strip">${[['Entrada',s.entry],['Intervalo',s.break_start],['Retorno',s.break_end],['Saída',s.departure]].map(x=>`<div class="time-cell"><small>${x[0]}</small><b>${x[1]}</b></div>`).join('')}</div></div>`).join('')}</div>`:empty('Nenhuma jornada cadastrada','Informe os horários contratuais de cada colaborador.','clock');}
function frequency(employeeId){if(employeeId&&Number(emp(employeeId).punch_exempt))return '<div class="note">Dispensado de ponto. Sem cobrança de marcações, faltas ou atrasos. O horário informado é apenas de referência.</div>';const rows=data.punches.filter(p=>!employeeId||p.employee_id===employeeId);return `<div class="card padded-table">${table(['Colaborador','Data','Marcação','Hora de Brasília','Previsto'],rows.map(p=>{const s=data.schedules.find(s=>s.employee_id===p.employee_id);const key={'Entrada':'entry','Saída para intervalo':'break_start','Retorno do intervalo':'break_end','Saída':'departure'}[p.kind];return `<tr><td><a href="#colaborador/${p.employee_id}">${person(emp(p.employee_id))}</a></td><td>${date(p.at)}</td><td>${esc(p.kind)}</td><td>${time(p.at)}</td><td>${Number(emp(p.employee_id).punch_exempt)?'Dispensado de ponto':esc(s?.[key]||'Sem jornada')}</td></tr>`;}))}</div>`;}
function documentCards(employeeId,staff=true){const rows=data.documents.filter(d=>!employeeId||d.employee_id===employeeId);return rows.length?rows.map(d=>`<article class="document"><div class="document-top"><small>PROTOCOLO RH-${String(d.id).padStart(5,'0')}</small>${pill(d.status)}</div><b>${esc(d.category)}</b><p>${staff?esc(emp(d.employee_id).name)+' · ':''}${date(d.start)} a ${date(d.end)}</p><p>${esc(d.original_name)}</p>${d.notes?`<p>${esc(d.notes)}</p>`:''}${d.review?`<div class="note">Resposta do RH: ${esc(d.review)}</div>`:''}<div class="action-row">${btn('Baixar arquivo','download',d.id,'small','download')}${staff?btn('Analisar','review-document',d.id,'small','edit'):''}</div></article>`).join(''):empty('Nenhum documento enviado','Os envios aparecerão aqui com seu protocolo.');}
function profilePage(id){const e=emp(id);if(!data.employees.some(x=>x.id===Number(id)))return empty('Colaborador não encontrado');const tabs=[['resumo','Visão geral'],['jornada','Jornada'],['ponto','Ponto'],['ferias','Férias e folgas'],['documentos','Documentos'],['historico','Histórico']];let body='';
  if(currentTab==='resumo')body=`<div class="grid-2"><div class="card"><div class="card-head"><h2>Informações cadastrais</h2>${btn('Editar cadastro','employee',e.id,'small','edit')}</div><div class="details">${[['CPF',e.cpf||'Não informado'],['E-mail',e.email||'Não informado'],['Telefone',e.phone||'Não informado'],['Cargo',e.role],['Setor',e.sector||'Não definido'],['Admissão',date(e.admission)],['Situação',e.status],['Controle de ponto',Number(e.punch_exempt)?'Dispensado de ponto':'Com controle de ponto'],...personalFields.map(([key,label])=>[label,key==='birthday'?date(personalData(e)[key]):(personalData(e)[key]||'Não informado')])].map(x=>`<div><small>${x[0]}</small><b>${esc(x[1])}</b></div>`).join('')}</div><div class="divider"></div><small>Observações do RH</small><p>${esc(e.notes||'Sem observações registradas.')}</p></div><div class="card"><div class="card-head"><h2>Rotinas do colaborador</h2></div><div class="quick-grid"><button class="quick" data-action="tab" data-id="jornada">${icon('clock')}Consultar jornada</button><button class="quick" data-action="leave" data-employee="${e.id}" data-id="Férias">${icon('sun')}Programar férias</button><button class="quick" data-action="leave" data-employee="${e.id}" data-id="Folga">${icon('calendar')}Programar folga</button><button class="quick" data-action="document" data-id="${e.id}">${icon('file')}Anexar documento</button></div><div class="note space-top">O prontuário reúne os registros vinculados a esta pessoa. Os dados de jornada precisam ser cadastrados conforme o contrato.</div></div></div>`;
  if(currentTab==='jornada')body=`<div class="action-row space-top">${btn('Definir jornada','schedule',e.id)}</div><div class="space-top">${scheduleCards(e.id)}</div>`;
  if(currentTab==='ponto')body=frequency(e.id);
  if(currentTab==='ferias')body=`<div class="action-row">${btn('Nova solicitação','leave','Férias')}${btn('Programar folga','leave','Folga','', 'calendar')}</div><div class="card padded-table space-top">${leaveRows(data.leaves.filter(l=>l.employee_id===e.id))}</div>`;
  if(currentTab==='documentos')body=`<div class="action-row">${btn('Solicitar documentos por link','doc-request',e.id,'small','file')}${btn('Anexar documento','document',e.id)}</div><div class="card space-top">${documentCards(e.id)}</div>`;
  if(currentTab==='historico'){const events=[{at:e.admission+'T12:00:00',action:'Admissão registrada',detail:e.role},...data.punches.filter(x=>x.employee_id===e.id).map(x=>({at:x.at,action:x.kind,detail:'Marcação de ponto'})),...data.documents.filter(x=>x.employee_id===e.id).map(x=>({at:x.created,action:'Documento enviado',detail:x.category})),...data.leaves.filter(x=>x.employee_id===e.id).map(x=>({at:x.start+'T12:00:00',action:x.kind,detail:`${date(x.start)} a ${date(x.end)} · ${x.status}`}))].sort((a,b)=>b.at.localeCompare(a.at));body=`<div class="card"><h2>Linha do tempo</h2>${events.map(x=>`<div class="activity"><span class="activity-mark">${icon('activity')}</span><div><b>${esc(x.action)}</b><small>${date(x.at)} · ${esc(x.detail)}</small></div></div>`).join('')}</div>`;}
  return `<a class="back-link" href="#equipe">${icon('back')}Voltar para colaboradores</a><div class="action-row profile-report">${btn('Relatório deste funcionário','report',e.id,'','file')}</div><div class="profile-hero"><div class="avatar">${initials(e.name)}</div><div><h1>${esc(e.name)}</h1><p>${esc(e.role)} · ${esc(e.sector||'Sem setor')} &nbsp; ${pill(e.status)}</p></div></div><div class="tabs">${tabs.map(t=>`<button class="tab ${currentTab===t[0]?'active':''}" data-action="tab" data-id="${t[0]}">${t[1]}</button>`).join('')}</div>${body}`;
}
function render(){clearInterval(clockTimer);if(!user)return;if(user.role==='employee'){if(pageId()==='tarefas'){app.innerHTML=people.employeeTasks();return;}renderPortal(location.pathname==='/ponto'?'ponto':'atestados');return;}const id=pageId();let html='';
  if(location.pathname==='/ponto'||location.pathname==='/atestados'){renderPortal(location.pathname.slice(1));return;}
  if(['premiacao','organizacao','talentos','jornadas','horarios','indicadores','tarefas'].includes(id))html=people.page(id==='horarios'?'jornadas':id);
  else if(id==='pendencias-documentais')html=documentRequests.page();
  else if(id==='sistema')html=systemPage();
  else if(id==='importacao')html=importPage();
  else if(id==='relatorios')html=reportPage();
  else if(id.startsWith('colaborador/'))html=profilePage(id.split('/')[1]);
  else if(id==='dashboard')html=dashboard();
  else if(id==='equipe')html=employeesPage();
  else if(id==='frequencia')html=pointPage();
  else if(id==='escalas'||id==='ferias')html=leavesPage(id);
  else if(id==='horarios')html=heading('Organização de jornada','Horários de trabalho','Dias, entrada, intervalo e saída por colaborador.',btn('Definir jornada','schedule'))+scheduleCards();
  else if(id==='setores')html=heading('Todo o colégio conectado','Setores do colégio','Pessoas, responsáveis e equipes em uma visão organizada.',btn('Novo setor','sector'))+`<div class="grid-3">${data.sectors.map(s=>`<div class="card"><div class="card-head"><span class="stat-icon">${icon('building')}</span><span class="tag">${data.employees.filter(e=>e.sector_id===s.id).length} pessoas</span></div><div class="card-head"><h2>${esc(s.name)}</h2>${btn("Editar","sector-edit",s.id,"small","edit")}</div><p><small>Responsável: ${esc(s.responsible||'Não definido')}</small></p><div class="divider"></div>${data.employees.filter(e=>e.sector_id===s.id).map(e=>`<a href="#colaborador/${e.id}"><div class="activity">${person(e)}</div></a>`).join('')||'<small>Nenhum colaborador vinculado.</small>'}</div>`).join('')||`<div class="card">${empty('Cadastre o primeiro setor','Ex.: Pedagógico, Recepção ou Administrativo.','building')}</div>`}</div>`;
  else if(id==='documentos')html=heading('Prontuário digital','Documentos e atestados','Analise os envios e acompanhe a resposta de cada protocolo.',btn('Anexar documento','document'))+`<div class="note">Arquivos JPG, PNG e PDF de até 5 MB. O acesso é restrito ao RH e ao próprio colaborador. Não é necessário informar diagnóstico ou CID.</div><div class="grid-2">${documentCards()}</div>`;
  else if(id==='usuarios')html=heading('Cada pessoa, seu acesso','Usuários e acessos','Contas individuais para o portal e para o ponto na recepção.',btn('Criar acesso','user'))+`<div class="note">O administrador de RH gerencia colaboradores e acessos individuais. O administrador geral gerencia a aplicação, as migrações, a identidade visual e os perfis administrativos na Administração do sistema. Cada colaborador consulta apenas seus próprios registros.</div><div class="card padded-table">${table(['Nome','Login','Perfil','Situação'],data.users.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.login)}</td><td>${esc(roleLabel(u.role))}</td><td>${pill(u.active?'Ativo':'Inativo')}</td></tr>`))}</div>`;
  else if(id==='auditoria')html=heading('Rastreabilidade','Histórico de alterações','Últimos 200 eventos: acessos, cadastros, documentos e decisões do RH.')+`<div class="card padded-table">${table(['Data','Hora','Usuário','Ação','Detalhe'],data.audit.map(a=>`<tr><td>${date(a.at)}</td><td>${time(a.at)}</td><td>${esc(a.actor)}</td><td>${esc(a.action)}</td><td>${esc(a.detail)}</td></tr>`))}</div>`;
  else html=empty('Página não encontrada');
  layout(html,id);
}
function renderAuth(setup=false){clearInterval(clockTimer);app.innerHTML=`<main class="auth"><section class="auth-brand">${brand()}<div><div class="eyebrow">Instituto Educacional Radeane</div><h1>Mais tempo<br>para cuidar<br>de <em>pessoas.</em></h1><p>Da primeira entrada ao próximo capítulo. A rotina de todo o colégio, conectada em um só lugar.</p></div><small>GESTÃO DE PESSOAS · RADEANE</small></section><section class="auth-content"><div class="auth-panel">${brand()}<div class="eyebrow">${setup?'Vamos começar':'Bem-vindo de volta'}</div><h2>${setup?'Seu RH começa aqui.':location.pathname==='/ponto'?'Registre sua presença.':location.pathname==='/atestados'?'Portal do colaborador.':'Entre no seu espaço.'}</h2><p>${setup?'Crie a conta do administrador geral do sistema. Os dados serão salvos no banco privado do RH.':'Use sua conta individual para acessar os registros autorizados.'}</p><form class="form" data-form="${setup?'setup':'login'}">${setup&&requiresSetupToken?field('Código de instalação fornecido pelo responsável técnico','setup_token','password'):''}${setup?field('Seu nome','name'):''}${field(setup?'E-mail ou login do RH':'Login','login')}${setup?field('Crie uma senha (mínimo de 12 caracteres)','password','password'):'<label>Senha<input name="password" type="password" required maxlength="200" autocomplete="current-password"></label>'}<div class="form-error" role="alert"></div><button class="btn primary" type="submit">${setup?'Criar conta e começar':'Entrar com segurança'}${icon('arrow')}</button></form><div class="demo-intro"><button class="btn" data-action="demo">Explorar demonstração ${icon('arrow')}</button><small>Conheça as três áreas com dados fictícios.</small></div><div class="auth-links"><a href="/">Sistema de RH</a><a href="/ponto">Ponto no tablet</a><a href="/atestados">Atestados</a><a href="/banco-de-talentos">Banco de talentos</a></div></div></section></main>`;}
function renderPortal(kind){
  const isAdmin=isManager(), e=emp(user.employee_id), ownId=user.employee_id;
  const tools=`<div class="action-row">${isAdmin?btn('Painel RH','panel','','small','grid'):''}${demo?btn(isAdmin?'Testar como funcionário':'Voltar ao RH','demo-role',isAdmin?'employee':'admin','small','people'):''}${btn('Sair','logout','','small','exit')}</div>`;
  const header=`<header class="portal-header">${brand()}${tools}</header><nav class="action-row portal-nav"><a class="btn small" href="/#tarefas">Minhas tarefas e entregas</a><a class="btn small" href="/atestados" data-action="portal" data-id="atestados">${icon("file")}Atestados e solicitações</a><a class="btn small" href="/ponto" data-action="portal" data-id="ponto">${icon("clock")}Meu ponto</a></nav>`;
  if(kind==='ponto') {
    const kinds=['Entrada','Saída para intervalo','Retorno do intervalo','Saída'],last=data.punches.find(p=>p.employee_id===ownId), next=!last||last.kind==='Saída'?'Entrada':kinds[kinds.indexOf(last.kind)+1];
    app.innerHTML=`<main class="kiosk">${header}${banner()}<div class="kiosk-main"><div class="eyebrow">Recepção · Ponto do colaborador</div><div class="clock-live"><span class="status-dot"></span>Hora de Brasília${demo?' · Simulação':''}</div><div class="clock" id="clock">--:--</div><div class="clock-date" id="clock-date"></div><div class="card"><h2>${isAdmin?'Uma conta para cada pessoa':'Olá, '+esc(e.name.split(' ')[0])+'.'}</h2><p class="muted">${isAdmin?'Entre com o acesso individual do funcionário para registrar a presença.':'Confira o tipo de marcação antes de confirmar.'}</p>${Number(e.punch_exempt)?'<div class="note space-top">Você está dispensado de ponto. Não é necessário registrar marcações.</div>':''}${isAdmin?`<div class="note space-top">O RH não registra ponto em nome dos colaboradores. ${demo?'Use “Testar como funcionário” para experimentar.':'Saia da conta administrativa e entre com a conta do colaborador.'}</div>`:`<div class="kiosk-person">${person(e)}</div>`}<div class="punch-grid">${kinds.map((k,i)=>`<button class="punch-btn ${!isAdmin&&next===k?'next':''}" data-action="punch" data-id="${esc(k)}" ${isAdmin||Number(e.punch_exempt)||next!==k?'disabled':''}>${icon(['exit','coffee','coffee','exit'][i])}${k}</button>`).join('')}</div>${last&&!isAdmin?`<small>Último registro: ${esc(last.kind)} · ${date(last.at)} às ${time(last.at)}</small>`:''}</div><div class="phone-note">${demo?'Demonstração sem validade de ponto.':'Versão local em validação. Ainda não homologada para uso como ponto oficial.'}<br>Ao terminar, saia da sua conta para liberar o tablet para a próxima pessoa.</div></div></main>`;
    const tick=()=>{document.querySelector('#clock').textContent=new Date().toLocaleTimeString('pt-BR',{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit',second:'2-digit'});document.querySelector('#clock-date').textContent=new Date().toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo',weekday:'long',day:'numeric',month:'long',year:'numeric'});};tick();clockTimer=setInterval(tick,1000);return;
  }
  app.innerHTML=`<main class="portal">${header}${banner()}<div class="portal-heading"><div class="eyebrow">Seu cuidado, com praticidade</div><h1>Envie seu atestado.<br>Acompanhe por aqui.</h1><p>Uma foto ou PDF, algumas informações e pronto. O RH recebe o documento e você acompanha a análise pelo protocolo.</p></div>${isAdmin?`<div class="note">Você está na conta do RH. ${demo?'Use “Testar como funcionário” para conhecer o envio individual.':'Para testar o envio do colaborador, entre com uma conta individual.'} Documentos também podem ser anexados pelo prontuário no painel.</div>`:''}<div class="portal-grid"><div class="card"><div class="card-head"><h2>Novo documento</h2><span class="tag">${icon('shield')}Acesso individual</span></div>${isAdmin?empty('Acesso do colaborador','Cada pessoa envia documentos vinculados à sua própria conta.','shield'):`<form class="form" data-form="portal-document">${documentFields(ownId,false)}<div class="form-error" role="alert"></div><button class="btn primary" type="submit">${icon('upload')}Enviar para o RH</button></form>`}</div><div><div class="card"><div class="card-head"><h2>Meus envios</h2><span class="tag">${isAdmin?0:data.documents.filter(d=>d.employee_id===ownId).length} documentos</span></div><div class="certificate-list">${isAdmin?empty('Entre como colaborador','O histórico individual aparecerá aqui.'):documentCards(ownId,false)}</div></div><div class="note space-top">JPG, PNG ou PDF · Até 5 MB por arquivo.<br>Envie uma imagem nítida, com o documento completo. Não é necessário preencher diagnóstico ou CID.</div>${!isAdmin?`<div class="action-row">${btn('Solicitar férias ou folga','leave','Férias','','calendar')}${btn('Alterar senha','password','','','settings')}</div>`:''}</div></div></main>`;
  if(!isAdmin) app.querySelector("main").insertAdjacentHTML("beforeend",`<section class="space-top"><div class="card-head"><h2>Minhas solicitações de férias e folgas</h2></div><div class="card padded-table">${leaveRows(data.leaves.filter(l=>l.employee_id===ownId),false)}</div></section><section class="space-top"><div class="card-head"><h2>Minha jornada de trabalho</h2></div>${scheduleCards(ownId)}</section>`);
}
function employeeForm(id){const e=id?emp(id):{};openModal(id?'Editar colaborador':'Novo colaborador',`<form class="form" data-form="employee" data-id="${id||''}">${field('Nome completo','name','text',e.name)}${field('CPF','cpf','text',e.cpf||'',!id)}<div class="form-2">${field('Cargo (pode ser completado depois)','role','text',e.role,false)}${select('Setor','sector_id','<option value="">Selecione</option>'+options(data.sectors,e.sector_id)).replace(' required','')}</div><div class="form-2">${field('E-mail','email','email',e.email,false)}${field('Telefone','phone','tel',e.phone,false)}</div><div class="form-2">${field('Data de admissão','admission','date',e.admission,false)}${id?select('Situação','status',['Ativo','Inativo'].map(s=>`<option ${s===e.status?'selected':''}>${s}</option>`).join('')):''}</div>${select('Controle de ponto','punch_exempt',`<option value="0" ${!Number(e.punch_exempt)?'selected':''}>Com controle de ponto</option><option value="1" ${Number(e.punch_exempt)?'selected':''}>Dispensado de ponto</option>`)}<div class="form-note">Para quem está dispensado, os horários são apenas de referência, sem cobrança de marcações, faltas ou atrasos.</div><h3>Dados pessoais e endereço</h3><div class="form-2">${personalFields.map(([key,label])=>field(label,'personal_'+key,key==='birthday'?'date':'text',personalData(e)[key]||'',false)).join('')}</div>${noteField('Observações do RH (opcional)',e.notes)}${formEnd('Salvar colaborador')}</form>`);}
function formEnd(label='Salvar'){return `<div class="form-error" role="alert"></div><div class="modal-foot"><button class="btn" type="button" data-action="close">Cancelar</button><button class="btn primary" type="submit">${esc(label)}</button></div>`;}
function openModal(title,body){modal.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="icon-btn" data-action="close" aria-label="Fechar">${icon('close')}</button></div><div class="modal-body">${body}</div>`;modal.showModal();}
function docTypeOptions(all=false){return ['Atestado médico','Atestado odontológico','Declaração de comparecimento','Outro documento justificativo',...(all?['Documento pessoal','Trabalhista']:[])].map(t=>`<option>${t}</option>`).join('');}
function documentFields(id,staff){return `${staff?select('Colaborador','employee_id','<option value="">Selecione</option>'+options(data.employees,id)):`<input type="hidden" name="employee_id" value="${id}">`}${select('Tipo de documento','category',docTypeOptions(staff))}<div class="form-2">${field('Início do período','start','date')}${field('Fim do período','end','date')}</div>${noteField()}<label class="upload-area">${icon('upload')}Anexe uma foto ou PDF<input name="file" type="file" accept="image/jpeg,image/png,application/pdf" required><span class="form-note">Até 5 MB · JPG, PNG e PDF. No celular, você pode usar a câmera pelo seletor de arquivos.</span></label><label class="check"><input type="checkbox" name="confirm" required>Conferi os dados e o arquivo. Entendo que o documento será analisado pelo RH.</label>`;}
function leaveForm(kind,id){const profile=pageId().startsWith('colaborador/')?Number(pageId().split('/')[1]):null;const selected=id||profile||user.employee_id;openModal('Férias, folgas e ausências',`<form class="form" data-form="leave">${isManager()?select('Colaborador','employee_id','<option value="">Selecione</option>'+options(data.employees,selected)):`<input type="hidden" name="employee_id" value="${user.employee_id}">`}${select('Tipo','kind',['Férias','Folga','Ausência'].map(s=>`<option ${s===kind?'selected':''}>${s}</option>`).join(''))}<div class="form-2">${field('Início','start','date')}${field('Fim','end','date')}</div>${noteField()}<div class="form-note">A solicitação ficará pendente até a análise do RH.</div>${formEnd('Registrar solicitação')}</form>`);}
function scheduleForm(id){const s=data.schedules.find(s=>s.employee_id===Number(id))||{};openModal('Horários de trabalho',`<form class="form" data-form="schedule">${select('Colaborador','employee_id','<option value="">Selecione</option>'+options(data.employees,id))}<label>Dias trabalhados</label><div class="schedule-days">${['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map((d,i)=>`<label><input type="checkbox" name="days" value="${i}" ${JSON.parse(s.days||'[]').includes(i)?'checked':''}>${d}</label>`).join('')}</div><div class="form-2">${field('Entrada','entry','time',s.entry)}${field('Saída para intervalo','break_start','time',s.break_start)}${field('Retorno do intervalo','break_end','time',s.break_end)}${field('Saída','departure','time',s.departure)}</div><div class="form-note">Para dispensados de ponto, informe apenas um horário de referência. Para os demais, informe a jornada contratual. Esta versão aceita uma jornada fixa no mesmo dia; turnos noturnos e escalas alternadas precisam de evolução.</div>${formEnd('Salvar jornada')}</form>`);}
function reviewForm(type,id){const doc=type==='document',r=data[doc?'documents':'leaves'].find(x=>x.id===Number(id));if(!r)return;openModal(doc?'Analisar documento':'Analisar solicitação',`<p><b>${esc(emp(r.employee_id).name)}</b></p><p class="muted">${esc(r.category||r.kind)} · ${date(r.start)} a ${date(r.end)}</p><form class="form space-top" data-form="review" data-resource="${doc?'documents':'leaves'}" data-id="${id}">${select('Decisão','status',(doc?['Em análise','Aceito','Pendente de correção','Recusado']:['Aprovado','Recusado','Pendente']).map(s=>`<option ${s===r.status?'selected':''}>${s}</option>`).join(''))}<label>Justificativa / resposta<textarea name="review" maxlength="2000">${esc(r.review||'')}</textarea><span class="form-note">Obrigatória para recusa ou pedido de correção.</span></label>${formEnd('Salvar análise')}</form>`);}
async function reload(){if(!demo)data=await api('/data');render();}
async function download(id){if(demo){const file=demoFiles.get(Number(id));if(!file){toast('Este registro é ilustrativo e não possui arquivo anexado.');return;}const a=document.createElement('a');a.href=`data:${file.mime};base64,${file.base64}`;a.download=file.filename;a.click();return;}const r=await fetch(`/api/documents/${id}/file`);if(!r.ok){const b=await r.json();throw Error(b.error);}const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=data.documents.find(d=>d.id===Number(id))?.original_name||'documento';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el){const row=event.target.closest('tr[data-person-row]');if(row&&!event.target.closest('a'))location.hash=row.querySelector('a').hash;return;}event.preventDefault();const {action,id}=el.dataset;try{
  if(await documentRequests.action(action,id,el))return;
  if(await people.action(action,id,el))return;
  if(await managementAction(action,id,el))return;
  if(action==='demo'){demo=true;user={id:1,name:'Equipe de RH',role:'system_admin',employee_id:null};makeDemo();render();}
  else if(action==='exit-demo'){demo=false;user=null;data=null;demoFiles.clear();const s=await api('/status');history.pushState({},'','/');renderAuth(s.setup);}
  else if(action==='logout'){if(!demo)await api('/logout','POST',{});if(demo){demo=false;demoFiles.clear();}user=null;const s=await api('/status');renderAuth(s.setup);}
  else if(action==='menu')document.querySelector('.shell')?.classList.toggle('menu-open');
  else if(action==='close')modal.close();
  else if(action==='employee')employeeForm(id);
  else if(action==='sector')openModal('Novo setor',`<form class="form" data-form="sector">${field('Nome do setor','name')}${field('Responsável','responsible','text','',false)}${formEnd('Cadastrar setor')}</form>`);
  else if(action==='leave')leaveForm(id,el.dataset.employee);
  else if(action==='schedule')scheduleForm(id);
  else if(action==='tab'){currentTab=id;render();}
  else if(action==='document')openModal('Anexar documento',`<form class="form" data-form="document">${documentFields(id,true)}${formEnd('Enviar documento')}</form>`);
  else if(action==='review-document')reviewForm('document',id);
  else if(action==='review-leave')reviewForm('leave',id);
  else if(action==='download')await download(id);
  else if(action==='user')openModal('Criar acesso individual',`<form class="form" data-form="user">${select('Colaborador','employee_id','<option value="">Selecione</option>'+options(data.employees.filter(e=>e.status==='Ativo'&&!data.users.some(u=>u.employee_id===e.id))))}${field('Login individual','login')}${field('Senha (mínimo 12 caracteres)','password','password')}<div class="note">Informe as credenciais ao colaborador por um canal seguro. Ele poderá trocar a senha pelo portal. Recuperação por e-mail ainda não está disponível.</div>${formEnd('Criar acesso')}</form>`);
  else if(action==='password'){if(demo){toast('A alteração de senha fica disponível na conta real.');return;}openModal('Alterar senha',`<form class="form" data-form="password"><label>Senha atual<input name="current" type="password" autocomplete="current-password" required></label>${field('Nova senha (mínimo 12 caracteres)','password','password')}${formEnd('Alterar e sair')}</form>`);}
  else if(action==='portal'){history.pushState({},'',`/${id}`);render();window.scrollTo(0,0);}
  else if(action==='panel'){history.pushState({},'','/#dashboard');render();window.scrollTo(0,0);}
  else if(action==='demo-role'){user=id==='employee'?{id:2,name:'Ana Oliveira',role:'employee',employee_id:2}:{id:1,name:'Equipe de RH',role:'system_admin',employee_id:null};render();}
  else if(action==='punch'){openModal('Confirmar marcação',`<p>Você vai registrar <b>${esc(id)}</b> para <b>${esc(user.name)}</b>.</p><p class="muted">O horário será registrado no momento da confirmação.</p><form class="form space-top" data-form="punch"><input type="hidden" name="kind" value="${esc(id)}">${formEnd('Confirmar ponto')}</form>`);}
}catch(e){toast(e.message);}});
document.addEventListener('input',e=>{if(e.target.matches('[data-filter], [data-sector-filter]'))filterPeople();});
document.addEventListener('change',e=>{if(e.target.matches('[data-sector-filter]'))filterPeople();if(e.target.matches('[name="start"]')){const end=e.target.form?.querySelector('[name="end"]');if(end){end.min=e.target.value;if(!end.value)end.value=e.target.value;}}});
function filterPeople(){const search=document.querySelector('[data-filter="people"]')?.value.toLowerCase()||'',sector=document.querySelector('[data-sector-filter]')?.value||'';document.querySelectorAll('[data-person-row]').forEach(r=>r.hidden=!(r.dataset.search.includes(search)&&(!sector||r.dataset.sector===sector)));}
document.addEventListener('submit',async event=>{const form=event.target.closest('[data-form]');if(!form)return;event.preventDefault();const submit=form.querySelector('[type=submit]'),error=form.querySelector('.form-error'),type=form.dataset.form;submit.disabled=true;error.textContent='';const fd=new FormData(form),b=Object.fromEntries(fd.entries());try{
  if(await documentRequests.submit(type,form,b,fd))return;
  if(await people.submit(type,form,b,fd))return;
  if(await managementSubmit(type,form,b,fd))return;
  if(['setup','login'].includes(type)){const result=await api('/'+type,'POST',b);user=result.user;csrf=result.csrf;data=await api('/data');render();return;}
  if(type==='employee'){b.personal_data=Object.fromEntries(personalFields.map(([key])=>[key,b['personal_'+key]||'']));await api('/employees'+(form.dataset.id?'/'+form.dataset.id:''),form.dataset.id?'PATCH':'POST',b);}
  else if(type==='sector')await api('/sectors','POST',b);
  else if(type==='schedule'){b.days=fd.getAll('days').map(Number);if(!b.days.length)throw Error('Selecione pelo menos um dia.');const t=[b.entry,b.break_start,b.break_end,b.departure];if(t.some((v,i)=>i>0&&v<=t[i-1]))throw Error('Informe horários crescentes no mesmo dia.');await api('/schedules','POST',b);}
  else if(type==='leave'){if(b.end<b.start)throw Error('O fim precisa ser igual ou posterior ao início.');await api('/leaves','POST',b);}
  else if(type==='review'){if(['Recusado','Pendente de correção'].includes(b.status)&&!b.review.trim())throw Error('Informe a justificativa.');await api('/'+form.dataset.resource+'/'+form.dataset.id,'PATCH',b);}
  else if(type==='user')await api('/users','POST',b);
  else if(type==='password'){await api('/password','POST',b);modal.close();user=null;renderAuth(false);toast('Senha alterada. Entre novamente.');return;}
  else if(type==='punch'){await api('/punches','POST',b);modal.close();await reload();toast(demo?'Marcação simulada.':'Ponto registrado. Saindo da conta para liberar o tablet.');if(!demo){await api('/logout','POST',{});user=null;renderAuth(false);}return;}
  else if(type==='document'||type==='portal-document'){
    const file=fd.get('file');if(!file?.size)throw Error('Selecione um arquivo.');if(file.size>5*1024*1024)throw Error('O arquivo deve ter até 5 MB.');if(!['application/pdf','image/jpeg','image/png'].includes(file.type))throw Error('Use JPG, PNG ou PDF.');if(b.end<b.start)throw Error('O fim precisa ser igual ou posterior ao início.');
    const bytes=new Uint8Array(await file.arrayBuffer());const signature=bytes[0]===0xff&&bytes[1]===0xd8&&bytes[2]===0xff||[137,80,78,71,13,10,26,10].every((v,i)=>bytes[i]===v)||String.fromCharCode(...bytes.slice(0,5))==='%PDF-';if(!signature)throw Error('O arquivo não possui um formato válido.');
    let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));b.base64=btoa(binary);b.filename=file.name;b.mime=file.type;delete b.file;await api('/documents','POST',b);
  }
  modal.close();await reload();toast(demo?'Alteração aplicada na demonstração.':'Registro salvo com sucesso.');
}catch(e){error.textContent=e.message;}finally{submit.disabled=false;}});
window.addEventListener('hashchange',()=>{currentTab='resumo';render();window.scrollTo(0,0);});
window.addEventListener('popstate',()=>render());
async function init(){if(location.pathname.startsWith('/enviar-documentos/')){await documentRequests.publicPage();return;}if(location.pathname==='/banco-de-talentos'){await people.publicPage();return;}try{const status=await api('/status');requiresSetupToken=Boolean(status.setup_requires_token);if(status.setup){renderAuth(true);return;}try{const me=await api('/me');user=me.user;csrf=me.csrf;data=await api('/data');render();}catch{renderAuth(false);}}catch(e){app.innerHTML=empty('Não foi possível conectar ao servidor','Inicie o sistema com o arquivo Iniciar RH.cmd.');}}
const people=createPeople({esc,field,select,btn,heading,table,pill,empty,openModal,formEnd,api,render,reload,toast,data:()=>data,user:()=>user,demo:()=>demo,modal:()=>modal});
const documentRequests=createDocumentRequests({esc,field,select,btn,heading,table,pill,formEnd,openModal,api,render,toast,data:()=>data,user:()=>user,demo:()=>demo});
init();

let importPreview=null, systemInfo=null, systemLoading=false, reportResult=null;
let reportQuery={type:'frequency',start:localDay().slice(0,7)+'-01',end:localDay(),employee_id:'',sector_id:''};
function importPage(){
  return heading('Cadastro em lote','Importar colaboradores','Excel (.xlsx) ou CSV com Nome, CPF, Telefone e Setor.')+`<div class="note">Nome é obrigatório. CPF pode ficar pendente somente com a opção abaixo marcada. Colunas opcionais: Cargo, Email e Dispensado de ponto (Sim/Não). Admissão e jornada podem ser completadas depois. CPFs inválidos ou repetidos não são gravados. O arquivo precisa conter apenas valores, sem fórmulas.</div><div class="card"><form class="form" data-form="import-preview"><label>Escolha a planilha<input type="file" name="file" accept=".csv,.xlsx" required></label><label class="check"><input type="checkbox" name="allow_missing_cpf">Permitir CPF em branco e completar depois. CPF preenchido deve ser válido; nomes repetidos sem CPF não serão importados.</label><div class="action-row"><button class="btn primary" type="submit">${icon('search')}Ler e conferir planilha</button>${btn('Baixar modelo CSV','import-template','','','download')}</div><div class="form-error" role="alert"></div><small>Até 5 MB e 2.000 linhas por arquivo. A prévia dura 30 minutos.</small></form></div>${importPreview?`<div class="card space-top"><div class="card-head"><h2>Confira antes de importar</h2><div class="action-row">${pill(importPreview.valid+' linhas válidas')}${pill(importPreview.invalid+' com erros')}</div></div>${table(['Linha','Nome','CPF','Telefone','Setor','Cargo','Ponto','Conferência'],importPreview.rows.map(r=>`<tr><td>${r.line}</td><td>${esc(r.name)}</td><td>${esc(r.cpf||'Pendente')}</td><td>${esc(r.phone||'—')}</td><td>${esc(r.sector||'A definir')}</td><td>${esc(r.role||'—')}</td><td>${r.punch_exempt?'Dispensado':'Com controle'}</td><td>${r.errors.length?`<span class="tag red">${esc(r.errors.join(' · '))}</span>`:('<span class="tag green">Pronto para importar</span>'+((r.warnings||[]).length?'<br><small>CPF pendente de preenchimento</small>':''))}</td></tr>`))}<form class="form space-top" data-form="import-commit">${importPreview.unknown_sectors.length?'<h3>Setores ainda não cadastrados</h3><p class="form-note">Escolha um setor existente ou autorize a criação de um novo.</p>':''}${importPreview.unknown_sectors.map((s,i)=>select(esc(s),'sector_'+i,'<option value="">Selecione</option><option value="create">Criar este setor: '+esc(s)+'</option>'+options(data.sectors))).join('')}<label class="check"><input type="checkbox" name="confirmed" required>Conferi os dados. Importar somente as ${importPreview.valid} linhas válidas e ignorar ${importPreview.invalid} linhas com erro.</label><div class="form-error" role="alert"></div><div class="action-row"><button class="btn primary" type="submit" ${!importPreview.valid?'disabled':''}>${icon('upload')}Confirmar importação</button>${btn('Descartar prévia','discard-import','','','close')}</div></form></div>`:''}`;
}
function systemPage(){
  if(user.role!=='system_admin')return empty('Acesso exclusivo do administrador geral','A operação do RH permanece nas telas de pessoas.','shield');
  if(!systemInfo&&!systemLoading){systemLoading=true;api('/system').then(r=>{systemInfo=r;systemLoading=false;render();}).catch(e=>{systemLoading=false;toast(e.message);});}
  if(!systemInfo)return heading('Administração técnica','Administração do sistema','Consultando a aplicação e as migrações…');
  const info=systemInfo,pending=info.migrations.filter(m=>!m.applied),settings=info.settings||{};
  return heading('Administrador geral','Administração do sistema','Configuração técnica, migrações, identidade visual e segregação de acessos.',btn('Criar administrador','tech-user','','primary','shield'))+`<div class="note">Administrador geral: gerencia a aplicação inteira e os perfis administrativos. Administrador de RH: opera funcionários, jornadas, importações e relatórios, sem executar migrações nem alterar as configurações técnicas.</div><div class="grid-3">${[['Aplicação',info.version],['Ambiente',info.runtime],['Banco de dados',info.database==='mysql'?'MySQL':info.database==='sqlite'?'SQLite · prévia local':info.database]].map(x=>`<div class="card"><small>${x[0]}</small><h2 class="space-top">${esc(x[1])}</h2></div>`).join('')}</div><div class="card space-top"><div class="card-head"><h2>Migrações do banco</h2>${btn(pending.length?'Executar '+pending.length+' migração(ões)':'Conferir migrações','migration-check','','primary','settings')}</div><div class="note">Somente migrações versionadas incluídas no código podem ser executadas. O sistema gera uma cópia privada do banco antes de aplicar alterações. Este painel não aceita SQL digitado.</div>${table(['Versão','Alteração','Situação','Aplicada em'],info.migrations.map(m=>`<tr><td>${esc(m.version)}</td><td>${esc(m.name)}</td><td>${pill(m.changed?'Código alterado':m.applied?'Aplicada':'Pendente')}</td><td>${date(m.applied_at)}</td></tr>`))}</div><div class="grid-2 space-top"><div class="card"><div class="card-head"><h2>Identidade do portal</h2></div><form class="form" data-form="system-settings">${field('Nome no portal','institution','text',settings.institution||'Portal Radeane')}${select('Fonte dos títulos','font',['Sora','Inter'].map(f=>`<option ${f===(settings.font||'Sora')?'selected':''}>${f}</option>`).join(''))}${field('Cor principal','accent','color',settings.accent||'#cf1034')}<div class="form-error" role="alert"></div><button class="btn primary" type="submit">Salvar identidade visual</button></form></div><div class="card"><div class="card-head"><h2>Estrutura privada da aplicação</h2></div>${Object.entries(info.structure).map(([k,v])=>`<div class="activity"><span class="activity-mark">${icon('file')}</span><div><b>${esc(k)}</b><small>${esc(v)}</small></div></div>`).join('')}</div></div><div class="card padded-table space-top"><div class="card-head"><h2>Usuários e perfis do sistema</h2></div>${table(['Pessoa','Login','Perfil','Situação',''],data.users.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.login)}</td><td>${esc(roleLabel(u.role))}</td><td>${pill(u.active?'Ativo':'Inativo')}</td><td>${btn('Gerenciar','manage-access',u.id,'small','shield')}</td></tr>`))}</div>`;
}
function reportFields(){return `<div class="form-2">${select('Relatório','type',[['frequency','Frequência — marcações'],['attendance','Frequência — apuração preliminar'],['leaves','Férias, folgas e ausências'],['documents','Documentos e atestados'],['employee','Cadastro do funcionário'],['indicators','Indicadores de premiação'],['awards','Conferência e concessões'],['work','Jornadas e vigências'],['tasks','Tarefas e entregas'],['talents','Banco de talentos']].map(([v,t])=>`<option value="${v}" ${v===reportQuery.type?'selected':''}>${t}</option>`).join(''))}${select('Colaborador','employee_id','<option value="">Todos os colaboradores</option>'+options(data.employees,reportQuery.employee_id)).replace(' required','')}</div><div class="form-2">${field('Início','start','date',reportQuery.start)}${field('Fim','end','date',reportQuery.end)}</div>${select('Setor','sector_id','<option value="">Todos os setores</option>'+options(data.sectors,reportQuery.sector_id)).replace(' required','')}`;}
function reportPage(){return heading('Conferência do RH','Relatórios','Consulte a equipe ou escolha uma pessoa e um período.')+`<div class="card report-controls"><form class="form" data-form="report">${reportFields()}<div class="form-error" role="alert"></div><button type="submit" class="btn primary">${icon('file')}Gerar relatório</button></form></div>${reportResult?`<section class="card space-top report-output"><div class="card-head"><div><h2>${esc(reportResult.title)}</h2><small>${date(reportResult.start)} a ${date(reportResult.end)} · ${reportResult.rows.length} registros</small></div><div class="action-row">${btn('Baixar CSV','report-csv','','','download')}${btn('Imprimir / PDF','report-print','','','file')}</div></div><div class="action-row">${Object.entries(reportResult.summary||{}).map(([k,v])=>pill(k+': '+v)).join('')}</div><div class="note">${esc(reportResult.notice)}</div>${table(reportResult.headers,reportResult.rows.map(row=>`<tr>${row.map(cell=>`<td>${esc(cell)}</td>`).join('')}</tr>`))}</section>`:''}`;}
async function managementAction(action,id,el){
  if(action==='import-open'){location.hash='importacao';return true;}
  if(action==='discard-import'){importPreview=null;render();return true;}
  if(action==='import-template'){const blob=new Blob(['\uFEFFNome;CPF;Telefone;Setor\r\n'],{type:'text/csv;charset=utf-8'});saveBlob(blob,'modelo-colaboradores-radeane.csv');return true;}
  if(action==='report'){reportQuery={...reportQuery,employee_id:id||'',sector_id:''};openModal('Relatório do funcionário',`<form class="form" data-form="report">${reportFields()}${formEnd('Gerar relatório')}</form>`);return true;}
  if(action==='report-csv'){const query=new URLSearchParams({...reportQuery,format:'csv'}),r=await fetch('/api/reports?'+query);if(!r.ok){const result=await r.json();throw Error(result.error);}saveBlob(await r.blob(),'rh-'+reportQuery.type+'.csv');return true;}
  if(action==='report-print'){document.body.classList.add('printing-report');window.print();document.body.classList.remove('printing-report');return true;}
  if(action==='migration-check'){
    if(demo){toast('As migrações estão disponíveis na conta real do administrador geral.');return true;}systemInfo=await api('/system');const pending=systemInfo.migrations.filter(m=>!m.applied);if(!pending.length){render();toast('Banco atualizado. Não há migrações pendentes.');return true;}
    openModal('Executar migrações',`<p>Serão aplicadas ${pending.length} migração(ões) incluídas nesta versão:</p><ul>${pending.map(m=>`<li>${esc(m.version)} · ${esc(m.name)}</li>`).join('')}</ul><div class="note">Uma cópia privada do banco será criada antes da execução. No MySQL, mudanças de estrutura não têm rollback automático.</div><form class="form" data-form="migrations"><label class="check"><input type="checkbox" required>Conferi as alterações e quero aplicar esta atualização do banco.</label>${formEnd('Criar cópia e aplicar')}</form>`);return true;
  }
  if(action==='tech-user'){openModal('Criar acesso administrativo',`<form class="form" data-form="tech-user">${field('Nome','name')}${field('Login individual','login')}${field('Senha inicial (mínimo 12 caracteres)','password','password')}${select('Perfil','role','<option value="rh_admin">Administrador de RH</option><option value="system_admin">Administrador geral do sistema</option>')}<div class="note">O perfil geral pode alterar a aplicação, executar migrações e gerenciar todos os acessos. O perfil de RH cuida da operação de pessoas.</div>${formEnd('Criar administrador')}</form>`);return true;}
  if(action==='manage-access'){const u=data.users.find(u=>u.id===Number(id));if(!u)return true;openModal('Gerenciar acesso',`<p><b>${esc(u.name)}</b> · ${esc(u.login)}</p><form class="form space-top" data-form="manage-access" data-id="${u.id}">${select('Perfil','role',[['rh_admin','Administrador de RH'],['system_admin','Administrador geral do sistema'],...(u.employee_id?[['employee','Colaborador']]:[])].map(([v,t])=>`<option value="${v}" ${u.role===v?'selected':''}>${t}</option>`).join(''))}${select('Acesso','active',`<option value="1" ${u.active?'selected':''}>Ativo</option><option value="0" ${!u.active?'selected':''}>Inativo</option>`)}<div class="form-note">A alteração encerra as sessões desse usuário. Seu próprio acesso geral não pode ser removido por esta tela.</div>${formEnd('Salvar acesso')}</form>`);return true;}
  if(action==='sector-edit'){const s=data.sectors.find(s=>s.id===Number(id));openModal('Editar setor',`<form class="form" data-form="sector-edit" data-id="${id}">${field('Nome do setor','name','text',s.name)}${field('Responsável','responsible','text',s.responsible,false)}${formEnd('Salvar setor')}</form>`);return true;}
  return false;
}
function saveBlob(blob,filename){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function managementSubmit(type,form,b,fd){
  if(type==='import-preview'){
    const file=fd.get('file');if(!file?.size)throw Error('Escolha uma planilha.');if(file.size>5*1024*1024)throw Error('O arquivo deve ter até 5 MB.');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));importPreview=await api('/import/preview','POST',{filename:file.name,base64:btoa(binary),allow_missing_cpf:fd.has('allow_missing_cpf')});render();toast('Prévia preparada. Nenhum colaborador foi gravado ainda.');return true;
  }
  if(type==='import-commit'){const sector_map={};importPreview.unknown_sectors.forEach((s,i)=>sector_map[s]=b['sector_'+i]);const result=await api('/import/commit','POST',{token:importPreview.token,sector_map});importPreview=null;await reload();toast(`${result.imported} colaboradores importados; ${result.skipped} linhas ignoradas.`);return true;}
  if(type==='report'){reportQuery={type:b.type,start:b.start,end:b.end,employee_id:b.employee_id||'',sector_id:b.sector_id||''};reportResult=await api('/reports?'+new URLSearchParams(reportQuery));modal.close();if(form.dataset.point!==undefined){render();}else if(location.hash!=='#relatorios')location.hash='relatorios';else render();return true;}
  if(type==='migrations'){const result=await api('/system/migrations','POST',{});modal.close();systemInfo=await api('/system');await reload();toast(`${result.applied} migração(ões) aplicada(s). Cópia do banco salva na pasta privada.`);return true;}
  if(type==='system-settings'){await api('/system/settings','POST',b);systemInfo=null;await reload();document.querySelector('link[href^="/theme.css"]').href='/theme.css?v='+Date.now();toast('Identidade visual salva.');return true;}
  if(type==='tech-user'){await api('/system/users','POST',b);modal.close();await reload();toast('Acesso administrativo criado.');return true;}
  if(type==='manage-access'){b.active=Number(b.active);await api('/system/users/'+form.dataset.id,'PATCH',b);modal.close();await reload();toast('Permissões atualizadas.');return true;}
  if(type==='sector-edit'){await api('/sectors/'+form.dataset.id,'PATCH',b);modal.close();await reload();toast('Setor atualizado.');return true;}
  return false;
}

function pointPage(){return heading('Conferência por equipe e pessoa','Frequência e ponto','Filtre o setor, escolha o colaborador e consulte o período completo.')+`<div class="card"><form class="form" data-form="report" data-point>${select('Consulta','type','<option value="frequency">Marcações por dia</option><option value="attendance" '+(reportQuery.type==='attendance'?'selected':'')+'>Apuração automática preliminar</option>')}<div class="form-2">${select('Setor','sector_id','<option value="">Todos os setores</option>'+options(data.sectors,reportQuery.sector_id)).replace(' required','')}${select('Colaborador','employee_id','<option value="">Todos os colaboradores</option>'+options(data.employees.filter(e=>!reportQuery.sector_id||Number(e.sector_id)===Number(reportQuery.sector_id)),reportQuery.employee_id)).replace(' required','')}</div><div class="form-2">${field('Início','start','date',reportQuery.start)}${field('Fim','end','date',reportQuery.end)}</div><div class="form-error" role="alert"></div><button class="btn primary" type="submit">Consultar ponto</button></form></div>`+(reportResult?.title?.startsWith('Frequência')?`<section class="card space-top report-output"><div class="card-head"><h2>${date(reportResult.start)} a ${date(reportResult.end)}</h2><div class="action-row">${btn('Baixar CSV','report-csv','','','download')}${btn('Imprimir / PDF','report-print','','','file')}</div></div><p>${reportResult.rows.length} registros</p><div class="action-row">${Object.entries(reportResult.summary||{}).map(([k,v])=>pill(k+': '+v)).join('')}</div><div class="note">${esc(reportResult.notice)}</div>${table(reportResult.headers,reportResult.rows.map(row=>'<tr>'+row.map(cell=>'<td>'+esc(cell)+'</td>').join('')+'</tr>'))}</section>`:'');}
document.addEventListener('change',event=>{if(event.target.matches('form[data-point] [name="sector_id"]')){const form=event.target.form;const people=data.employees.filter(e=>!event.target.value||Number(e.sector_id)===Number(event.target.value));form.querySelector('[name="employee_id"]').innerHTML='<option value="">Todos os colaboradores</option>'+options(people);}});
